/* ---------------------------------------- */
/* MedicCare.module.css — CSS Module           */
/* ---------------------------------------- */

.root {
  /* Spine roles */
  --vt-surface: #ffffff;
  --vt-surface-2: #f9f9f9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #247cff;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #0d47a1; /* darkened for 4.5:1 on surface-2 */
  --vt-accent-on-deep: #6ea8fe;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink-soft);
  line-height: 1.6;
  padding-top: 94px;
  position: relative;
}

/* ---- Typography ---- */
.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  font-weight: 600;
  line-height: 1.2;
}

.root h1 {
  font-size: 48px;
  font-weight: 700;
}

.root h2 {
  font-size: 36px;
  font-weight: 700;
}

.root h3 {
  font-size: 32px;
}

.root h4 {
  font-size: 28px;
}

.root h5 {
  font-size: 24px;
}

.root h6 {
  font-size: 22px;
}

.root p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* ---- Navbar ---- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.1);
  padding: 20px 0;
}

.navIn {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
}

.logo {
  display: inline-block;
}

.brand {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 1.2;
}

.navLinks {
  display: flex;
  gap: 30px;
  align-items: center;
  flex-wrap: wrap;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  padding: 15px 0;
  transition: color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-ink);
}

/* ---- Hero ---- */
.hero {
  position: relative;
}

.heroSlider {
  position: relative;
  overflow: hidden;
  height: 580px;
}

.sliderTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
}

.slide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
}

.slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 20px;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  background: transparent;
  transition: all 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--vt-line);
  color: var(--vt-accent);
  text-align: center;
  transition: top 0.3s cubic-bezier(0.19, 1, 0.56, 1);
  line-height: 40px;
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  margin: 0;
}

/* ---- Sections ---- */
.section {
  /* base */
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

/* ---- About ---- */
.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.aboutContent {
  flex: 0 0 60%;
  max-width: 60%;
  padding-right: 30px;
}

/* ---- Gallery ---- */
.gallery {
  /* no padding */
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  flex: 0 0 50%;
  max-width: 50%;
  padding: 0;
  position: relative;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

.gallerySub {
  position: absolute;
  bottom: 20px;
  left: 20px;
  background: var(--vt-surface);
  padding: 5px 15px;
  border-radius: 20px;
  font-size: 14px;
  color: var(--vt-ink);
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

/* ---- Timeline ---- */
.timelineTitle {
  text-align: center;
  margin-bottom: 4rem;
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  transform: translateX(-50%);
  z-index: 1;
}

.timelineNode {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  position: relative;
  margin-bottom: 3rem;
}

.timelineContent {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
  position: relative;
  z-index: 2;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  margin: 0;
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  font-size: 1.5rem;
  line-height: 1.4;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
}

.timelineIcon {
  position: relative;
  z-index: 10;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 80px;
  height: 80px;
  margin: 0 20px;
}

.timelineIcon::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  z-index: 1;
}

.timelineIcon span {
  position: relative;
  z-index: 2;
  font-size: 2rem;
  color: var(--vt-accent);
  line-height: 80px;
  text-align: center;
  display: block;
}

.timelineDate {
  padding: 10px 0;
  font-weight: 600;
  color: var(--vt-ink);
}

/* Alternating layout */
.timelineNode:nth-child(odd) .timelineContent {
  grid-column: 1;
  grid-row: 1;
  text-align: right;
}

.timelineNode:nth-child(odd) .timelineDate {
  grid-column: 3;
  grid-row: 1;
  text-align: left;
}

.timelineNode:nth-child(even) .timelineContent {
  grid-column: 3;
  grid-row: 1;
  text-align: left;
}

.timelineNode:nth-child(even) .timelineDate {
  grid-column: 1;
  grid-row: 1;
  text-align: right;
}

/* Arrows on dark title */
.timelineNode:nth-child(odd) .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode:nth-child(even) .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

/* ---- Footer ---- */
.footer {
  background: var(--vt-surface-2);
  padding-top: 4rem;
  padding-bottom: 4rem;
  border-top: 1px solid var(--vt-line);
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 30px;
  justify-content: space-between;
}

.footerCol {
  flex: 1;
  min-width: 200px;
}

.footerCol h5 {
  margin-bottom: 1.5rem;
  color: var(--vt-ink);
}

.footerCol p {
  margin-bottom: 0.5rem;
  font-size: 16px;
}

.hoursList {
  list-style: none;
  padding: 0;
  margin: 0;
}

.hoursList li {
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--vt-line);
  display: flex;
  justify-content: space-between;
  font-size: 16px;
}

.copyright {
  font-size: 14px;
  color: var(--vt-ink-soft);
}

/* ---- Responsive ---- */
@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .root h1 {
    font-size: 38px;
  }

  .root h2 {
    font-size: 32px;
  }

  .root h3 {
    font-size: 26px;
  }

  .root h4 {
    font-size: 24px;
  }

  .root h5 {
    font-size: 20px;
  }

  .root h6 {
    font-size: 18px;
  }

  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .nav {
    padding-top: 10px;
    padding-bottom: 10px;
  }

  .navLinks a {
    padding-top: 5px;
    padding-bottom: 10px;
  }

  .heroSlider {
    height: auto;
  }

  .sliderTrack {
    height: auto;
  }

  .slide {
    height: auto;
  }

  .slide img {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: auto;
    right: auto;
    width: auto;
    margin-top: -100px;
    margin-bottom: -100px;
    padding: 2rem;
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  }

  .aboutContent {
    flex: 0 0 100%;
    max-width: 100%;
    padding-right: 0;
    margin-bottom: 2rem;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .timeline::before {
    top: 60px;
    left: 47px;
    height: 90%;
    transform: none;
  }

  .timelineNode {
    grid-template-columns: 60px 1fr;
    grid-template-rows: auto auto;
    column-gap: 15px;
    margin-bottom: 2rem;
  }

  .timelineNode:nth-child(odd) .timelineContent,
  .timelineNode:nth-child(even) .timelineContent {
    grid-column: 2;
    grid-row: 1;
    text-align: left;
  }

  .timelineNode:nth-child(odd) .timelineDate,
  .timelineNode:nth-child(even) .timelineDate {
    grid-column: 2;
    grid-row: 2;
    text-align: left;
  }

  .timelineIcon {
    grid-column: 1;
    grid-row: 1 / span 2;
    margin: 0;
  }

  .timelineIcon::before {
    width: 75px;
    height: 75px;
  }

  .timelineIcon span {
    line-height: 75px;
  }

  .timelineNode:nth-child(odd) .timelineContent h3::after,
  .timelineNode:nth-child(even) .timelineContent h3::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-surface-deep);
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 42px;
  }

  .timelineIcon {
    width: 70px;
    height: 70px;
  }

  .timelineIcon::before {
    width: 70px;
    height: 70px;
  }

  .timelineIcon span {
    line-height: 70px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks {
    gap: 12px;
  }

  .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }

  .navIn {
    padding: 0 10px;
    gap: 10px;
  }

  .navLinks {
    gap: 15px;
    font-size: 14px;
  }

  .navLinks a {
    font-size: 14px;
    padding: 10px 0;
  }
}

@media screen and (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }

  .timelineIcon {
    width: 60px;
    height: 60px;
  }

  .timelineIcon::before {
    width: 60px;
    height: 60px;
  }

  .timelineIcon span {
    line-height: 60px;
    font-size: 1.5rem;
  }
}
